101→/* ── Build the sidebar DOM ────────────────────────────────────────── */
102→
103→function buildSidebar(el) {
104→  el.style.height = "100%";
105→  el.style.display = "flex";
106→  el.style.flexDirection = "column";
107→  el.style.fontFamily = "system-ui, -apple-system, sans-serif";
108→
109→  el.innerHTML = `
110→    <div class="sd-header">
111→      <span class="sd-header__title">${SIDEBAR_TITLE}</span>
112→      <span class="sd-header__status" id="sd-status"></span>
113→    </div>
114→    <div class="sd-stage-bar" id="sd-stage" style="display:none">
115→      <span class="sd-stage__label" id="sd-stage-label"></span>
116→      <span class="sd-stage__detail" id="sd-stage-detail"></span>
117→    </div>
118→    <div class="sd-messages" id="sd-messages">
119→      <div class="sd-message sd-message--system">
120→        <span class="sd-message__body">Ready. Type below.</span>
121→      </div>
122→    </div>
123→    <div class="sd-input-bar">
124→      <input
125→        type="text"
126→        id="sd-input"
127→        class="sd-input"
128→        placeholder="Ask me anything about your workflow..."
129→        autocomplete="off"
130→      />
131→      <button id="sd-send" class="sd-send-btn">Send</button>
132→    </div>
133→  `;
134→
135→  const messagesEl = el.querySelector("#sd-messages");
136→  const inputEl = el.querySelector("#sd-input");
137→  const sendBtn = el.querySelector("#sd-send");
138→  const statusEl = el.querySelector("#sd-status");
139→  const stageBar = el.querySelector("#sd-stage");
140→  const stageLabel = el.querySelector("#sd-stage-label");
141→  const stageDetail = el.querySelector("#sd-stage-detail");
142→
143→  let busy = false;
144→  let streamingEl = null; // element receiving streamed text deltas
145→
146→  function scrollToBottom() {
147→    messagesEl.scrollTop = messagesEl.scrollHeight;
148→  }
149→
150→  function setStage(stage, detail) {
151→    if (stage === "DONE" || !stage) {
152→      stageBar.style.display = "none";
153→      return;
154→    }
155→    stageBar.style.display = "flex";
156→    stageLabel.textContent = stage;
157→    stageDetail.textContent = detail || "";
158→  }
159→
160→  function setBusy(state) {
161→    busy = state;
162→    sendBtn.disabled = state;
163→    inputEl.disabled = state;
164→    sendBtn.textContent = state ? "..." : "Send";
165→  }
166→
167→  /* ── WebSocket message handler ────────────────────────────────── */
168→
169→  function handleAgentMessage(data) {
170→    switch (data.type) {
171→      case "connected":
172→        break;
173→
174→      case "text_delta":
175→        // Streaming: append text to current agent message
176→        if (!streamingEl) {
177→          streamingEl = createMessageEl("agent", "");
178→          messagesEl.appendChild(streamingEl);
179→        }
180→        const body = streamingEl.querySelector(".sd-message__body");
181→        body.textContent += data.text;
182→        scrollToBottom();
183→        break;
184→
185→      case "message":
186→        // Full message — replace streaming element or create new
187→        if (streamingEl) {
188→          const msgBody = streamingEl.querySelector(".sd-message__body");
189→          msgBody.textContent = data.content;
190→          streamingEl = null;
191→        } else {
192→          messagesEl.appendChild(createMessageEl("agent", data.content));
193→        }
194→        scrollToBottom();
195→        break;
196→
197→      case "stage":
198→        setStage(data.stage, data.detail);
199→        if (data.stage === "DONE") {
200→          streamingEl = null;
201→          setBusy(false);
202→        }
203→        break;
204→
205→      case "error":
206→        setStage(null);
207→        messagesEl.appendChild(createMessageEl("system", data.message));
208→        streamingEl = null;
209→        setBusy(false);
210→        scrollToBottom();
211→        break;
212→
213→      default:
214→        console.log("[SUPER DUPER] Unknown event:", data);
215→    }
216→  }
217→
218→  function handleStatus(status) {
219→    statusEl.textContent = status === "connected" ? "" : status;
220→    statusEl.className = `sd-header__status sd-header__status--${status}`;
221→  }
222→
223→  /* ── Connect ──────────────────────────────────────────────────── */
224→
225→  const conn = new AgentConnection(handleAgentMessage, handleStatus);
226→  conn.connect();
227→
228→  /* ── Send message ─────────────────────────────────────────────── */
229→
230→  async function sendMessage() {
231→    const text = inputEl.value.trim();
232→    if (!text || busy) return;
233→
234→    // Show user message
235→    messagesEl.appendChild(createMessageEl("user", text));
236→    inputEl.value = "";
237→    scrollToBottom();
238→
239→    // Capture current workflow from ComfyUI canvas
240→    let workflow = null;
241→    try {
242→      const result = await app.graphToPrompt();
243→      if (result && result.output) {
244→        workflow = result.output;
245→      }
246→    } catch (e) {
247→      console.warn("[SUPER DUPER] Could not capture workflow:", e);
248→    }
249→
250→    // Send to agent via WebSocket (include workflow if captured)
251→    const payload = { content: text };
252→    if (workflow) {
253→      payload.workflow = workflow;
254→    }
255→    const sent = conn.send("chat", payload);
256→    if (!sent) {
257→      messagesEl.appendChild(
258→        createMessageEl("system", "Not connected. Reconnecting...")
259→      );
260→      scrollToBottom();
261→      return;
262→    }
263→
264→    setBusy(true);
265→  }
266→
267→  sendBtn.addEventListener("click", sendMessage);
268→  inputEl.addEventListener("keydown", (e) => {
269→    if (e.key === "Enter" && !e.shiftKey) {
270→      e.preventDefault();
271→      sendMessage();
272→    }
273→  });
274→
275→  setTimeout(() => inputEl.focus(), 100);
276→}
